  const data = await atlassian(`${site}/rest/api/3/search/jql?jql=${encodeURIComponent(query)}&maxResults=5&fields=summary,status,resolution,labels,issuetype`);
  return (data.issues || []).map(i => ({ key: i.key, summary: i.fields.summary, status: i.fields.status?.name, resolution: i.fields.resolution?.name || 'Не указано', labels: i.fields.labels || [], issueType: i.fields.issuetype?.name || 'Development', source: 'jira-development', url: `${site}/browse/${encodeURIComponent(i.key)}` }));
